import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.CqGS6Fr9.js";const h=JSON.parse('{"title":"Building the project","description":"","frontmatter":{"pageId":"developers/build","contentRevision":5},"headers":[],"relativePath":"en/developers/build.md","filePath":"en/developers/build.md"}'),n={name:"en/developers/build.md"};function l(s,e,r,d,c,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="building-the-project" tabindex="-1">Building the project <a class="header-anchor" href="#building-the-project" aria-label="Permalink to &quot;Building the project&quot;">​</a></h1><p>Applies to: Rimlink 0.9.2 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>Use SDK 10.0.403 selected by global.json with rollForward=disable. Build in an isolated toolchain directory and record the loaded runtime as well as the SDK. Server and CLI runtimeconfigs require NETCore and ASP.NET 10.0.14 with RollForward=Disable. The mod uses the installed game runtime; rebuild it and the development companion when RimWorld changes.</p><p>Install the SDK pinned in global.json; package versions are centralized in Directory.Packages.props. From the repository root run:</p><p><code>dotnet build Rimlink.sln</code></p><p><code>dotnet test Rimlink.sln -nologo -v q</code></p><p>The mod is outside the solution: close the game and use PowerShell scripts/Build-ClientMod.ps1 -RimWorldDir &lt;game&gt; -InstallTo &lt;game/Mods&gt;. -BundleHarmony is only for local runs without separate Harmony, never releases. scripts/Package-Release.ps1 produces release ZIPs.</p><p>For the wiki: npm --prefix wiki ci --ignore-scripts, then run test:checks, check:content, check:reference, build and check:links. Node 24 is pinned separately. BridgeTools requires its separate Build-BridgeTools.ps1 and an installed game.</p><h2 id="build-track" tabindex="-1">From checkout to an assembled mod <a class="header-anchor" href="#build-track" aria-label="Permalink to &quot;From checkout to an assembled mod {#build-track}&quot;">​</a></h2><ol><li>Read global.json, install the matching SDK and inspect dotnet --info. Do not upgrade central dependencies to hide a local error.</li><li>Run dotnet build Rimlink.sln and dotnet test Rimlink.sln -nologo -v q from the root. This builds server/core/tools/tests, not the game mod.</li><li>The mod needs installed RimWorld 1.7 with Assembly-CSharp.dll and PowerShell. Close your own test game and pass -RimWorldDir plus a <strong>new -OutputDir</strong> to Build-ClientMod.ps1. Without -InstallTo it only assembles output; do not touch another session&#39;s Mods.</li><li>Inspect output About, Languages and Assemblies. Never bundle Harmony in a release; -BundleHarmony is local-only.</li><li>Installing into a test copy and running two clients is a separate acceptance stage, not implied by compilation.</li></ol><p>The script clears OutputDir: never point it at source, the game or your only data copy.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Do not replace a running game&#39;s DLLs or restart someone else&#39;s instance. A solution build proves neither mod compilation nor gameplay. Keep bin/obj/data/saves/secrets and generated wiki output out of commits.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./testing">Testing and acceptance</a></li><li><a href="./contributing">Contributing and wiki maintenance</a></li><li><a href="./../admins/hosting">Hosting and startup</a></li></ul>',16)])])}const m=t(n,[["render",l]]);export{h as __pageData,m as default};
